                    </div>
                </div>

                <div className="flex flex-col gap-6 md:gap-10">
                    {/* Contact Info Group - Side by Side on Mobile with Divider */}
                    <div className="flex flex-row items-start">
                        {/* Call Center */}
                        <div className="flex-1 space-y-2 md:space-y-4">
