"use client";

import React, { useState, useEffect } from "react";
import { MessageCircle } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import ChatModal from "./ChatModal";

/**
 * Floating chat widget for mobile ΓÇö appears at the bottom-right
 * only after the user has previously initiated a chat (laralabs_user_data exists).
 * Also exports a hook so the Navbar can check the same condition.
 */

export function useChatReady() {
  const [hasChatted, setHasChatted] = useState(false);

  useEffect(() => {
    const data = localStorage.getItem("laralabs_user_data");
    setHasChatted(!!data);

    // Listen for storage changes (in case user submits form in ChatModal)
    const handler = () => {
      const d = localStorage.getItem("laralabs_user_data");
      setHasChatted(!!d);
    };
    window.addEventListener("storage", handler);

    // Also poll briefly ΓÇö storage event only fires across tabs
    const interval = setInterval(handler, 2000);
    return () => {
      window.removeEventListener("storage", handler);
      clearInterval(interval);
    };
  }, []);

  return hasChatted;
}

export default function ChatWidget() {
  const hasChatted = useChatReady();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const [isNavOpen, setIsNavOpen] = useState(false);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check);

    const handleNavToggle = (e: Event) => {
      const customEvent = e as CustomEvent;
      setIsNavOpen(customEvent.detail.isOpen);
    };
    window.addEventListener("navbar-toggle", handleNavToggle);

    return () => {
      window.removeEventListener("resize", check);
      window.removeEventListener("navbar-toggle", handleNavToggle);
    };
  }, []);

  // Only render on mobile, only after user has chatted, and NOT when nav menu is open
  if (!isMobile || !hasChatted || isNavOpen) return null;

  return (
    <>
      {/* Floating Action Button */}
      <AnimatePresence>
        {!isModalOpen && (
          <motion.button
            initial={{ opacity: 0, scale: 0, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0, y: 20 }}
            transition={{ type: "spring", stiffness: 260, damping: 20 }}
            onClick={() => setIsModalOpen(true)}
            className="fixed bottom-6 right-6 z-[9998] w-14 h-14 rounded-full flex items-center justify-center shadow-2xl group border border-white/20 backdrop-blur-md"
            style={{
              background: "rgba(255, 255, 255, 0.15)",
              boxShadow: "0 8px 32px 0 rgba(31, 38, 135, 0.37)",
            }}
            aria-label="Open chat"
          >
            {/* Glass shine */}
            <span className="absolute inset-0 rounded-full bg-gradient-to-br from-white/30 via-transparent to-transparent pointer-events-none" />

            <MessageCircle className="w-6 h-6 text-white relative z-10 group-hover:scale-110 transition-transform" />
          </motion.button>
        )}
      </AnimatePresence>

      {/* Chat Modal */}
      <ChatModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        initialMessage=""
        onSubmit={() => setIsModalOpen(false)}
      />
    </>
  );
}

"use client";

import Link from "next/link";
import Image from "next/image";
import React, { useState } from "react";
import { Menu, X, MessageCircle } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useChatReady } from "./ChatWidget";
import ChatModal from "./ChatModal";

export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);
    const hasChatted = useChatReady();
    const [isChatOpen, setIsChatOpen] = useState(false);

    React.useEffect(() => {
        const event = new CustomEvent("navbar-toggle", { detail: { isOpen } });
        window.dispatchEvent(event);
        
        if (isOpen) {
            document.body.style.overflow = "hidden";
        } else {
            document.body.style.overflow = "unset";
        }
    }, [isOpen]);

    const navItems = [
        { name: "Home", href: "/" },
        { name: "Services", href: "/services" },
        { name: "Blog", href: "/blog" },
        { name: "About", href: "/about" },
        { name: "Join", href: "/join" },
        { name: "Contact", href: "/contact" },
    ];

    return (
        <>
            <nav className="fixed w-full z-[100] top-0 left-0 bg-transparent backdrop-blur-sm border-b border-white/10">
                <div className="w-full px-[5%] md:px-[10%] h-16 md:h-20 flex items-center justify-between">
                    <div className="flex-shrink-0 z-[101]">
                        <Link href="/" className="block" onClick={() => setIsOpen(false)}>
                            <Image
                                src="/logo.png"
                                alt="Logo"
                                width={120}
                                height={40}
                                className="h-8 md:h-10 w-auto object-contain"
                                priority
                            />
                        </Link>
                    </div>

                    {/* Desktop Menu */}
                    <div className="hidden md:block">
                        <div className="flex items-center space-x-8">
                            {navItems.map((item) => (
                                <Link
                                    key={item.name}
                                    href={item.href}
                                    className="text-sm font-medium text-gray-300 hover:text-white transition-colors"
                                >
                                    {item.name}
                                </Link>
                            ))}

                            {/* Chat button ΓÇö visible only after user has chatted */}
                            {hasChatted && (
                                <button
                                    onClick={() => setIsChatOpen(true)}
                                    className="text-sm font-medium text-gray-300 hover:text-white transition-colors"
                                >
                                    Chat
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Mobile Menu Button */}
                    <div className="md:hidden z-[101]">
                        <button
                            onClick={() => setIsOpen(!isOpen)}
                            suppressHydrationWarning
                            className="text-white focus:outline-none p-2"
                        >
                            {isOpen ? <X size={28} /> : <Menu size={28} />}
                        </button>
                    </div>

                    {/* Mobile Menu Overlay */}
                    <AnimatePresence>
                        {isOpen && (
                            <motion.div
                                initial={{ opacity: 0, y: -20 }}
                                animate={{ opacity: 1, y: 0 }}
                                exit={{ opacity: 0, y: -20 }}
                                transition={{ duration: 0.3 }}
                                className="fixed inset-0 bg-[#0a0a16]/95 backdrop-blur-xl z-[100] flex flex-col items-center justify-center space-y-8 md:hidden h-screen w-screen"
                            >
                                {navItems.map((item, index) => (
                                    <motion.div
                                        key={item.name}
                                        initial={{ opacity: 0, y: 20 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: 0.1 + index * 0.1 }}
                                    >
                                        <Link
                                            href={item.href}
                                            onClick={() => setIsOpen(false)}
                                            className="text-3xl font-serif italic text-white hover:text-blue-400 transition-colors"
                                        >
                                            {item.name}
                                        </Link>
                                    </motion.div>
                                ))}
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </nav>

            {/* Desktop Chat Modal (triggered from Navbar) */}
            <ChatModal
                isOpen={isChatOpen}
                onClose={() => setIsChatOpen(false)}
                initialMessage=""
                onSubmit={() => setIsChatOpen(false)}
            />
        </>
    );
}

