            ref={containerRef}
            className="flex"
            style={{ x, touchAction: "pan-y" }}
            drag="x"
            // Allow dragging but handle wrapping in useAnimationFrame
            onDragStart={() => setIsPaused(true)}
            onDragEnd={() => setIsPaused(false)}
          >
